CREATE TABLE IF NOT EXISTS regions (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS cities (id SERIAL PRIMARY KEY, region_id INT NOT NULL REFERENCES regions(id), name TEXT NOT NULL, UNIQUE(region_id,name));
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS interests (id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), region_id INT REFERENCES regions(id), city_id INT REFERENCES cities(id), university TEXT, age INT CHECK (age BETWEEN 13 AND 120), avatar_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS user_interests (user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, interest_id INT NOT NULL REFERENCES interests(id) ON DELETE CASCADE, PRIMARY KEY(user_id,interest_id));
CREATE TABLE IF NOT EXISTS organizers (id SERIAL PRIMARY KEY, user_id INT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('club','association','organization','company','individual')), description TEXT, logo_url TEXT, region_id INT REFERENCES regions(id), city_id INT REFERENCES cities(id), domain TEXT, contact TEXT, approved BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS events (id SERIAL PRIMARY KEY, organizer_id INT NOT NULL REFERENCES organizers(id), category_id INT NOT NULL REFERENCES categories(id), title TEXT NOT NULL, description TEXT NOT NULL, image_url TEXT, region_id INT NOT NULL REFERENCES regions(id), city_id INT REFERENCES cities(id), address TEXT NOT NULL, latitude NUMERIC(9,6), longitude NUMERIC(9,6), start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL, deadline TIMESTAMPTZ, price NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK(price>=0), capacity INT NOT NULL CHECK(capacity>0), conditions TEXT, contact TEXT, participation_type TEXT NOT NULL CHECK(participation_type IN ('direct','application')), status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published','cancelled')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS applications (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id INT NOT NULL REFERENCES events(id) ON DELETE CASCADE, message TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','waitlist')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS participants (user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id INT NOT NULL REFERENCES events(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id,event_id));
CREATE TABLE IF NOT EXISTS favorites (user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id INT NOT NULL REFERENCES events(id) ON DELETE CASCADE, PRIMARY KEY(user_id,event_id));
CREATE TABLE IF NOT EXISTS notifications (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, text TEXT NOT NULL, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reviews (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id INT NOT NULL REFERENCES events(id) ON DELETE CASCADE, rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,event_id));
CREATE INDEX IF NOT EXISTS events_region_start_idx ON events(region_id,start_at);
CREATE INDEX IF NOT EXISTS applications_event_status_idx ON applications(event_id,status);
